PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE event_years (
  id TEXT PRIMARY KEY,
  calendar_year INTEGER NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  source_notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), is_sample INTEGER NOT NULL DEFAULT 0 CHECK (is_sample IN (0, 1)), starts_on TEXT, ends_on TEXT,
  UNIQUE (calendar_year, name)
);
CREATE TABLE parks (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);
CREATE TABLE attractions (
  id TEXT PRIMARY KEY,
  event_year_id TEXT NOT NULL REFERENCES event_years (id) ON DELETE CASCADE,
  attraction_type TEXT NOT NULL CHECK (attraction_type IN ('house', 'scare_zone')),
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  -- Optional alternate/regional cut of the same attraction, e.g. a
  -- "Uncensored" or park-specific variant.
  variant_name TEXT,
  ip_type TEXT CHECK (ip_type IS NULL OR ip_type IN ('original', 'licensed')),
  franchise_name TEXT,
  short_summary TEXT,
  full_overview TEXT,
  story_lore TEXT,
  experience_description TEXT,
  development_notes TEXT,
  opening_date TEXT,
  closing_date TEXT,
  location_notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), is_sample INTEGER NOT NULL DEFAULT 0 CHECK (is_sample IN (0, 1)),
  UNIQUE (event_year_id, slug)
);
CREATE TABLE attraction_parks (
  attraction_id TEXT NOT NULL REFERENCES attractions (id) ON DELETE CASCADE,
  park_id TEXT NOT NULL REFERENCES parks (id) ON DELETE CASCADE,
  PRIMARY KEY (attraction_id, park_id)
);
CREATE TABLE characters (
  id TEXT PRIMARY KEY,
  attraction_id TEXT NOT NULL REFERENCES attractions (id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE attraction_relations (
  id TEXT PRIMARY KEY,
  attraction_id TEXT NOT NULL REFERENCES attractions (id) ON DELETE CASCADE,
  related_attraction_id TEXT NOT NULL REFERENCES attractions (id) ON DELETE CASCADE,
  relation_type TEXT NOT NULL CHECK (
    relation_type IN ('sequel', 'previous_version', 'same_franchise', 'related_concept')
  ),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (attraction_id != related_attraction_id),
  UNIQUE (attraction_id, related_attraction_id, relation_type)
);
CREATE TABLE attraction_sources (
  attraction_id TEXT NOT NULL REFERENCES attractions (id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
  PRIMARY KEY (attraction_id, source_id)
);
CREATE TABLE media (
  id TEXT PRIMARY KEY,
  attraction_id TEXT REFERENCES attractions (id) ON DELETE CASCADE,
  event_year_id TEXT REFERENCES event_years (id) ON DELETE CASCADE,
  media_type TEXT NOT NULL CHECK (
    media_type IN ('poster', 'promotional_image', 'logo', 'event_artwork', 'local_image')
  ),
  url TEXT,
  local_path TEXT,
  source_id TEXT REFERENCES sources (id) ON DELETE SET NULL,
  attribution TEXT,
  license_notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), distribution TEXT NOT NULL DEFAULT 'reference'
  CHECK (distribution IN ('reference', 'local', 'bundled')),
  CHECK (
    (attraction_id IS NOT NULL AND event_year_id IS NULL) OR
    (attraction_id IS NULL AND event_year_id IS NOT NULL)
  ),
  CHECK (url IS NOT NULL OR local_path IS NOT NULL)
);
CREATE TABLE user_ratings (
  id TEXT PRIMARY KEY,
  attraction_id TEXT NOT NULL UNIQUE REFERENCES attractions (id) ON DELETE CASCADE,
  theme REAL NOT NULL CHECK (theme >= 0 AND theme <= 5 AND theme = ROUND(theme * 2) / 2.0),
  fun REAL NOT NULL CHECK (fun >= 0 AND fun <= 5 AND fun = ROUND(fun * 2) / 2.0),
  fear REAL NOT NULL CHECK (fear >= 0 AND fear <= 5 AND fear = ROUND(fear * 2) / 2.0),
  total REAL GENERATED ALWAYS AS (theme + fun + fear) VIRTUAL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE user_notes (
  id TEXT PRIMARY KEY,
  attraction_id TEXT NOT NULL UNIQUE REFERENCES attractions (id) ON DELETE CASCADE,
  note TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE user_rankings (
  id TEXT PRIMARY KEY,
  scope TEXT NOT NULL,
  attraction_id TEXT NOT NULL REFERENCES attractions (id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE (scope, attraction_id)
);
CREATE TABLE user_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE IF NOT EXISTS "sources" (
  id TEXT PRIMARY KEY,
  source_type TEXT NOT NULL CHECK (
    source_type IN (
      'youtube', 'article', 'official_site', 'promotional', 'book',
      'podcast', 'interview', 'social_media', 'other'
    )
  ),
  title TEXT NOT NULL,
  url TEXT,
  publisher TEXT,
  published_at TEXT,
  notes TEXT,
  is_sample INTEGER NOT NULL DEFAULT 0 CHECK (is_sample IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE event_year_sources (
  event_year_id TEXT NOT NULL REFERENCES event_years (id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
  PRIMARY KEY (event_year_id, source_id)
);
CREATE INDEX idx_attractions_event_year ON attractions (event_year_id);
CREATE INDEX idx_characters_attraction ON characters (attraction_id);
CREATE INDEX idx_attraction_relations_attraction ON attraction_relations (attraction_id);
CREATE INDEX idx_media_attraction ON media (attraction_id);
CREATE INDEX idx_media_event_year ON media (event_year_id);
CREATE INDEX idx_user_rankings_scope ON user_rankings (scope, position);
COMMIT;
